from collections import Counter


def count_common(words):
    """Write a function to count the most common words in a dictionary.

    Return the four most common words in ``words`` as a list of
    ``(word, count)`` tuples, ordered from most to least common.
    Words with equal counts are ordered by their first occurrence,
    matching :meth:`collections.Counter.most_common`.
    """
    return Counter(words).most_common(4)
